  "Find next instance": "\u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u062A\u0627\u0644\u064A\u0629",
  "DUP": "\u0646\u0633\u062E",
  "FIND": "\u0628\u062D\u062B",
