  "Saving\u2026": "\u062C\u0627\u0631\u064D \u0627\u0644\u062D\u0641\u0638\u2026",
  "Unsaved": "\u063A\u064A\u0631 \u0645\u062D\u0641\u0648\u0638",
  "Saved \xB7 Not live yet": "\u0645\u062D\u0641\u0648\u0638 \xB7 \u0644\u0645 \u064A\u0635\u0628\u062D \u0645\u0628\u0627\u0634\u0631\u064B\u0627 \u0628\u0639\u062F",
  "Saved \xB7 Live": "\u0645\u062D\u0641\u0648\u0638 \xB7 \u0645\u0628\u0627\u0634\u0631",
  "Saved": "\u0645\u062D\u0641\u0648\u0638",
  "Editor history": "\u0633\u062C\u0644 \u0627\u0644\u0645\u062D\u0631\u0631",
  "Publishing\u2026": "\u062C\u0627\u0631\u064D \u0627\u0644\u0646\u0634\u0631\u2026",
  "Republish": "\u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0646\u0634\u0631",
  "Publish again": "\u0627\u0644\u0646\u0634\u0631 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649",
  "Publish": "\u0646\u0634\u0631",
  "Tayar Coding Assistance": "\u0645\u0633\u0627\u0639\u062F\u0629 Tayar \u0627\u0644\u0628\u0631\u0645\u062C\u064A\u0629",
  "UI Registry": "\u0633\u062C\u0644 \u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645",
  "Reading active project": "\u062C\u0627\u0631\u064D \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0646\u0634\u0637",
  "Project context unavailable": "\u0633\u064A\u0627\u0642 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D",
  "Loading open-source registries": "\u062C\u0627\u0631\u064D \u062A\u062D\u0645\u064A\u0644 \u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0645\u0635\u0627\u062F\u0631 \u0627\u0644\u0645\u0641\u062A\u0648\u062D\u0629",
  "Target project": "\u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0645\u0633\u062A\u0647\u062F\u0641",
  "Source policy": "\u0633\u064A\u0627\u0633\u0629 \u0627\u0644\u0645\u0635\u062F\u0631",
  "Files": "\u0627\u0644\u0645\u0644\u0641\u0627\u062A",
  "Folder": "\u0645\u062C\u0644\u062F",
  "Clear private session files": "\u0645\u0633\u062D \u0645\u0644\u0641\u0627\u062A \u0627\u0644\u062C\u0644\u0633\u0629 \u0627\u0644\u062E\u0627\u0635\u0629",
  "Full Feature Generator": "\u0645\u0648\u0644\u0651\u062F \u0627\u0644\u0645\u064A\u0632\u0627\u062A \u0627\u0644\u0643\u0627\u0645\u0644",
  "Registry anchors": "\u0645\u0631\u0627\u062C\u0639 \u0627\u0644\u0633\u062C\u0644",
  "Choose a target project to generate a feature pack.": "\u0627\u062E\u062A\u0631 \u0645\u0634\u0631\u0648\u0639\u064B\u0627 \u0645\u0633\u062A\u0647\u062F\u0641\u064B\u0627 \u0644\u0625\u0646\u0634\u0627\u0621 \u062D\u0632\u0645\u0629 \u0645\u064A\u0632\u0627\u062A.",
  "Component Kit Composer": "\u0645\u064F\u0646\u0634\u0626 \u062D\u0632\u0645\u0629 \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062A",
  "Kit is empty. Load a preset or add selected components.": "\u0627\u0644\u062D\u0632\u0645\u0629 \u0641\u0627\u0631\u063A\u0629. \u062D\u0645\u0651\u0644 \u0625\u0639\u062F\u0627\u062F\u064B\u0627 \u0645\u0633\u0628\u0642\u064B\u0627 \u0623\u0648 \u0623\u0636\u0641 \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062A \u0627\u0644\u0645\u062D\u062F\u062F\u0629.",
  "Clear kit": "\u0645\u0633\u062D \u0627\u0644\u062D\u0632\u0645\u0629",
  "Items": "\u0627\u0644\u0639\u0646\u0627\u0635\u0631",
  "Registry deps": "\u0627\u0639\u062A\u0645\u0627\u062F\u064A\u0627\u062A \u0627\u0644\u0633\u062C\u0644",
  "Compatibility": "\u0627\u0644\u062A\u0648\u0627\u0641\u0642",
  "Page Composer + Themes": "\u0645\u064F\u0646\u0634\u0626 \u0627\u0644\u0635\u0641\u062D\u0627\u062A + \u0627\u0644\u0633\u0645\u0627\u062A",
  "Section anchors": "\u0645\u0631\u0627\u062C\u0639 \u0627\u0644\u0623\u0642\u0633\u0627\u0645",
  "No strong registry anchors found for this page preset.": "\u0644\u0645 \u064A\u062A\u0645 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0645\u0631\u0627\u062C\u0639 \u0642\u0648\u064A\u0629 \u0641\u064A \u0627\u0644\u0633\u062C\u0644 \u0644\u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062F\u0627\u062F \u0627\u0644\u0645\u0633\u0628\u0642 \u0644\u0644\u0635\u0641\u062D\u0629.",
  "Project UI Audit": "\u062A\u062F\u0642\u064A\u0642 \u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639",
  "Choose a target project to run the UI audit.": "\u0627\u062E\u062A\u0631 \u0645\u0634\u0631\u0648\u0639\u064B\u0627 \u0645\u0633\u062A\u0647\u062F\u0641\u064B\u0627 \u0644\u062A\u0634\u063A\u064A\u0644 \u062A\u062F\u0642\u064A\u0642 \u0627\u0644\u0648\u0627\u062C\u0647\u0629.",
  "Score": "\u0627\u0644\u0646\u062A\u064A\u062C\u0629",
  "High": "\u0645\u0631\u062A\u0641\u0639",
  "Coverage": "\u0627\u0644\u062A\u063A\u0637\u064A\u0629",
  "No issues matched the current deterministic audit rules.": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0645\u0634\u0643\u0644\u0627\u062A \u062A\u0637\u0627\u0628\u0642 \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u062A\u062F\u0642\u064A\u0642 \u0627\u0644\u062D\u0627\u0644\u064A\u0629.",
  "All sources": "\u0643\u0644 \u0627\u0644\u0645\u0635\u0627\u062F\u0631",
  "Private Session": "\u062C\u0644\u0633\u0629 \u062E\u0627\u0635\u0629",
  "Animated only": "\u0627\u0644\u0645\u062A\u062D\u0631\u0643\u0629 \u0641\u0642\u0637",
  "No matching components.": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0645\u0643\u0648\u0646\u0627\u062A \u0645\u0637\u0627\u0628\u0642\u0629.",
  "Show 80 more": "\u0639\u0631\u0636 80 \u0625\u0636\u0627\u0641\u064A\u0629",
  "Open source": "\u0645\u0641\u062A\u0648\u062D \u0627\u0644\u0645\u0635\u062F\u0631",
  "Private session": "\u062C\u0644\u0633\u0629 \u062E\u0627\u0635\u0629",
  "Isolated live preview": "\u0645\u0639\u0627\u064A\u0646\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0645\u0639\u0632\u0648\u0644\u0629",
