  "V1 LIVE": "V1 \u0645\u0628\u0627\u0634\u0631",
  "VERIFY LIVE": "\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u062D\u064A\u0629",
  "Quality review completed.": "\u0627\u0643\u062A\u0645\u0644\u062A \u0645\u0631\u0627\u062C\u0639\u0629 \u0627\u0644\u062C\u0648\u062F\u0629.",
  "Website improvement": "\u062A\u062D\u0633\u064A\u0646 \u0627\u0644\u0645\u0648\u0642\u0639",
  "AI quality check failed.": "\u0641\u0634\u0644 \u0641\u062D\u0635 \u0627\u0644\u062C\u0648\u062F\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A.",
  "Automated builder audit is available, but the AI review could not complete.": "\u062A\u062F\u0642\u064A\u0642 \u0627\u0644\u0645\u0646\u0634\u0626 \u0627\u0644\u0622\u0644\u064A \u0645\u062A\u0627\u062D\u060C \u0644\u0643\u0646 \u0645\u0631\u0627\u062C\u0639\u0629 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0644\u0645 \u062A\u0643\u062A\u0645\u0644.",
