// src/modules/website-builder/core/editor-layout-style.ts
function bounded(value, fallback, min, max) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.min(max, Math.max(min, parsed)) : fallback;
}
function containerLayoutCss(container) {
  const direction = container.layout === "row" ? "row" : "column";
  const align = container.align === "start" ? "flex-start" : container.align === "end" ? "flex-end" : container.align === "stretch" ? "stretch" : "center";
  const justify = container.justify === "start" ? "flex-start" : container.justify === "end" ? "flex-end" : container.justify === "between" ? "space-between" : "center";
  const gap = bounded(container.gap, 16, 0, 80);
  const rowGap = bounded(container.rowGap, gap, 0, 80);
  const columns = Math.round(bounded(container.columns, 2, 1, 12));
  return [
    `display:${container.layout === "grid" ? "grid" : "flex"}`,
    `flex-direction:${direction}`,
    `flex-wrap:${container.wrap === false ? "nowrap" : "wrap"}`,
    `grid-template-columns:${container.layout === "grid" ? `repeat(${columns},minmax(0,1fr))` : "none"}`,
    `column-gap:${gap}px`,
    `row-gap:${rowGap}px`,
    `align-items:${align}`,
    `justify-content:${justify}`
  ];
}
function elementConstraintCss(style, suffix = "") {
  const width = bounded(style.width, 0, 0, 100);
  const minWidth = bounded(style.minWidth, 0, 0, 2400);
  const height = bounded(style.height, 0, 0, 2400);
  const minHeight = bounded(style.minHeight, 0, 0, 2400);
  const maxHeight = bounded(style.maxHeight, 0, 0, 2400);
  const aspectRatio = bounded(style.aspectRatio, 0, 0.1, 10);
  return [
    `width:${width ? `${width}%` : "auto"}${suffix}`,
    `min-width:${minWidth ? `${minWidth}px` : "0"}${suffix}`,
    `height:${height ? `${height}px` : "auto"}${suffix}`,
    `min-height:${minHeight ? `${minHeight}px` : "0"}${suffix}`,
    `max-height:${maxHeight ? `${maxHeight}px` : "none"}${suffix}`,
    `aspect-ratio:${aspectRatio || "auto"}${suffix}`
  ];
}

// src/modules/website-builder/core/editor-motion.ts
var ELEMENT_ANIMATIONS = [
  "none",
  "fade",
  "fade-up",
  "fade-down",
  "fade-left",
  "fade-right",
  "zoom-in",
  "zoom-out",
  "slide-up",
  "slide-down",
  "slide-left",
  "slide-right",
  "blur-in",
  "flip-in",
  "bounce-in"
];
function normalizeElementAnimation(value) {
  return typeof value === "string" && ELEMENT_ANIMATIONS.includes(value) ? value : "none";
}
function elementAnimationTransform(animation, distance) {
  if (animation === "fade-up" || animation === "slide-up") return `translate3d(0,${distance}px,0)`;
  if (animation === "fade-down" || animation === "slide-down") return `translate3d(0,-${distance}px,0)`;
  if (animation === "fade-left" || animation === "slide-left") return `translate3d(${distance}px,0,0)`;
  if (animation === "fade-right" || animation === "slide-right") return `translate3d(-${distance}px,0,0)`;
  if (animation === "zoom-in") return "scale(.86)";
  if (animation === "zoom-out") return "scale(1.14)";
  if (animation === "flip-in") return "perspective(900px) rotateX(-18deg)";
  if (animation === "bounce-in") return "translate3d(0,24px,0) scale(.94)";
  return "none";
}
function elementAnimationEasing(value) {
  const easing = value;
  if (easing === "linear") return "linear";
  if (easing === "ease") return "ease";
  if (easing === "spring") return "cubic-bezier(.34,1.56,.64,1)";
  return "cubic-bezier(.22,1,.36,1)";
}

// src/modules/website-builder/core/website-localization.ts
function normalizeWebsiteLocalization(value, fallbackLanguage = "en") {
  const defaultLanguage = value?.defaultLanguage === "ar" || value?.defaultLanguage === "sv" || value?.defaultLanguage === "en" ? value.defaultLanguage : fallbackLanguage;
  return {
    defaultLanguage,
    routeStrategy: value?.routeStrategy === "subdirectory" ? "subdirectory" : "flat"
  };
}
function isLocalizedHome(page, pages, homePageId) {
  if (page.id === homePageId) return true;
  const home = pages.find((item) => item.id === homePageId);
  const homeTranslationKey = home?.translationKey?.trim();
  return Boolean(homeTranslationKey && page.translationKey?.trim() === homeTranslationKey);
}
function websitePageOutputPath(page, pages, homePageId, localization) {
  const language = normalizePageLanguage(page.language, localization.defaultLanguage);
  const home = isLocalizedHome(page, pages, homePageId);
  if (localization.routeStrategy === "flat") {
    return page.id === homePageId ? "index.html" : `${normalizeSlug(page.slug)}.html`;
  }
  if (page.id === homePageId) return "index.html";
  const prefix = language === localization.defaultLanguage ? "" : `${language}/`;
  return home ? `${prefix}index.html` : `${prefix}${normalizeSlug(page.slug)}.html`;
}
function relativeWebsitePageHref(fromPath, toPath) {
  const fromDirectoryDepth = Math.max(0, fromPath.split("/").filter(Boolean).length - 1);
  return `${"../".repeat(fromDirectoryDepth)}${toPath}`;
}
function websitePathUrl(baseUrl, path, homeUsesIndexFile) {
  const normalizedBase = baseUrl.replace(/\/+$/, "");
  if (!normalizedBase) return "";
  if (path === "index.html" && !homeUsesIndexFile) return `${normalizedBase}/`;
  return `${normalizedBase}/${path}`;
}

